-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["720094d215a79304"] = { "Così potenziati, i Cinque Aspetti ricevettero il compito di difendere il mondo in assenza dei Titani. Con i draghi pronti a proteggere la loro creazione, i Titani lasciarono Azeroth per sempre. Purtroppo era solo questione di tempo prima che Sargeras venisse a sapere dell'esistenza del mondo appena nato....", "." },
  ["7202d2be524e2a00"] = { "Il Pantheon distrusse le cittadelle degli Dei Antichi e incatenò i cinque dèi malvagi nelle profondità del mondo. Senza il potere degli Dei Antichi a tenere i loro spiriti furiosi legati al mondo fisico, gli elementali furono banditi in un piano abissale, dove si sarebbero combattuti l'un l'altro per tutta l'eternità. Con la partenza degli elementali la natura si placò e il mondo trovò un'armonia pacifica. I Titani videro che la minaccia era contenuta e si misero al lavoro.", "." },
  ["722cf995e35da328"] = { "l'altro. Come di certo sarebbero stati gli elfi, i mezzorsi si infuriarono, ma reagirono in modo molto più violento e uccisero Dartol.\n\nI mezzorsi, almeno a quel tempo, non erano le creature corrotte che sono diventati. Erano ancora razionali e intelligenti, e i loro rapporti con il nostro popolo erano amichevoli.\n\nSpero che, se riuscirò a ricreare la verga con l'aiuto di una driade di nome Shael'dryn, potrò usarne il potere per aiutare il nostro popolo... e i mezzorsi.", "." },
  ["72773478b3db13a9"] = { "Al calare del crepuscolo dell'ultimo giorno delle loro fatiche, i Titani chiamarono il continente Kalimdor: «terra della luce stellare eterna».", "." },
  ["72792b5e4ec2eba6"] = { "Molti della nostra specie ricorrono all'arcano e al divino per trarne forza, ma noi la sappiamo più lunga, vero, {class}? Sappiamo che le nostre armi sono i nostri simboli sacri, lo scudo è il nostro libro di incantesimi e la maglia è la nostra saggezza.\n\nAnche nella non morte siamo forti, e diventeremo soltanto più forti.\n\nCercami nella locanda di ⟦Deathknell=Albamorta⟧. Ti parlerò ancora di queste e di altre questioni.\n\n-Dannal Stern, istruttore dei guerrieri", "." },
  ["72c6b0b328c52be3"] = { "Con la ⟦Holy Light=Luce Sacra⟧ che ci scalda le spalle e nuove scoperte ogni giorno, è un periodo entusiasmante per chi appartiene al popolo di Forgiardente. La Lega degli Esploratori fa progressi ogni giorno nella ricerca di risposte perdute da tempo a domande ancora più antiche. E ora abbiamo anche te tra i nostri fedeli, per aiutarci nella battaglia contro i trogg e contro ogni altra minaccia ai nostri confini.\n\nCercami quando hai tempo. Sarò nel retro di ⟦Anvilmar=Forgiamara⟧, appena su per la collina.\n\n- Branstock Khalder, istruttore dei sacerdoti", "." },
  ["72c815f82f3b2cba"] = { "Anche i fedeli cavalieri della morte di Ner'zhul e i suoi seguaci Shadowmoon furono trasformati dalle energie caotiche del demone. I malvagi incantatori furono fatti a pezzi e riplasmati in lich scheletrici. I demoni si erano assicurati che, anche nella morte, i seguaci di Ner'zhul lo servissero senza fare domande.", "." },
})
